-- State transitions declared for PurchaseOrder: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION buying.purchase_orders_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('cancelled', 'draft'), ('draft', 'cancelled'), ('draft', 'purchase'), ('draft', 'sent'), ('draft', 'to_approve'), ('purchase', 'cancelled'), ('purchase', 'draft'), ('sent', 'cancelled'), ('sent', 'draft'), ('sent', 'purchase'), ('sent', 'to_approve'), ('to_approve', 'cancelled'), ('to_approve', 'draft'), ('to_approve', 'purchase'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: purchase_orders.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_purchase_orders__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS purchase_orders_status_transition_check ON buying.purchase_orders;
CREATE TRIGGER purchase_orders_status_transition_check
    BEFORE UPDATE OF "status" ON buying.purchase_orders
    FOR EACH ROW EXECUTE FUNCTION buying.purchase_orders_status_transition_check();

